exercise.solution:
enum Rank {
  Rookie,
  Hacker,
  Legend
}

function rankName(rank: Rank): string {
  if (rank === Rank.Rookie) {
    return 'rookie';
  }
  if (rank === Rank.Hacker) {
    return 'hacker';
  }
  return 'legend';
}

function nextRank(rank: Rank): Rank {
  if (rank === Rank.Legend) {
    return Rank.Legend;
  }
  return rank + 1;
}

