exercise.solution:
function toSafeNumber(v: unknown): number {
  if (typeof v === 'number') {
    return v;
  }
  if (typeof v === 'string' && v !== '') {
    var n: number = Number(v);
    if (!isNaN(n)) {
      return n;
    }
  }
  return -1;
}
